# diagonal shift: shift row r by r*k
for m in ({5:5,7:0},{5:0,7:5}):
  for k in range(-3,4):
    p=np.vectorize(m.get)(Lg)
    for r in range(4):
      p[r]=np.roll(p[r],r*k)
    print(m,k,(p==Rg).sum())

def score(p): return (p==Rg).sum()
maps=[{5:5,7:0},{5:0,7:5}]
ops={'id':lambda x:x,'flipud':np.flipud,'fliplr':np.fliplr,'both':lambda x:np.flipud(np.fliplr(x)),'T':lambda x:x.T}
for name,op in ops.items():
  for m in maps:
    p=np.vectorize(m.get)(op(Lg))
    print(name,m,score(p))
